WINDOW = 200000
OPERATOR = "operator"
TIMEOUT = 120.0
LARGEST = 524288
ROOT = "chain1"
site = ContextVar("site", default=OPERATOR)
raised = None
actor = ""
accepts = None
type Show = Callable[[list[str]], list[int]]
type Filter = Callable[[list[tuple]], list[tuple]]


def ask(kind, on, *words):
  if isinstance(got := peek(a := act(kind, on, None, *words), Refused(a + " not done")), Refused):
    raise got
  return got


def span(lo: int, hi: int) -> Show:
  return lambda lines: list(range(1, len(lines) + 1)[lo - (lo > 0) : hi if hi >= 0 else hi + 1 or None])


def grep(pattern: str) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if re.search(pattern, line)]


def differs(old: list[str]) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if old[i - 1 : i] != [line]]


HEAD, TAIL, HIDDEN = span(1, 2000), span(-250, -1), span(0, 0)


def take(*ids: str, inside=True) -> Filter:
  return lambda facts: [a for a in facts if any(under(a[1], one) for one in ids) == inside]


def read(path: str, show: Show = HEAD, on="") -> Text:
  got = ask("read", on, path)
  if acting() and isinstance(got, Text) and (size := len(shown(got, show).encode())) > LARGEST:
    raise Refused(f"{path} shows {size} bytes, over {LARGEST}")
  show is HIDDEN or tell(on, path, got, show)
  return got


def write(text: Text, on="") -> Text:
  got = ask("write", on, Text(text.path, text.content))
  tell(on, text.path, got, differs(text.lines))
  return got


def turns(on="") -> list[tuple]:
  past, user, sent = [], [], []
  for it in transcript(on):
    match it:
      case ("reply", *_):
        sent += user
        user = []
      case ("done", about, _, [*_] as turn) if question(("reply", about)):
        past += [("user", "\n\n".join(sent), None, None), turn]
        sent = []
      case ("tell", *_, notes):
        user.append("\n".join(notes))
  return [*past, ("user", "\n\n".join(sent + user), None, None)]


def module(on="") -> dict:
  return (transcript(on, "module") or [[{}] * 4])[-1][3]


def program(on="") -> dict[str, str]:
  words = {}
  for x in transcript(on):
    match x:
      case ("module", *_):
        words = {}
      case ("run", *_, which, word, donor):
        words[donor or which] = word
  return words


def literal(v, into=None):
  isinstance(v, str) and get(v) and into is not None and into.add(v)
  match v:
    case Act():
      return f"Act({str(v)!r})" * (into is not None)
    case None | bool() | int() | float() | str() | Text() | Exit() | BaseException():
      return repr(v)
    case dict():
      s = [(literal(k, into), literal(y, into)) for k, y in v.items()]
      return all(p and o for p, o in s) and "{" + ", ".join(f"{p}: {o}" for p, o in s) + "}"
    case list() | tuple() | set():
      s = [literal(y, into) for y in v]
      j = ", ".join(s)
      return all(s) and (
        f"[{j}]"
        if isinstance(v, list)
        else f"({j}{',' * (len(s) == 1)})"
        if isinstance(v, tuple)
        else "{" + j + "}"
        if s
        else "set()"
      )
  return ""


def dump(*names: str, on="") -> str:
  here, out = module(on), {}
  for name in names:
    if name in here and callable(here[name]):
      text = next(
        (w for w in reversed(program(on).values()) if re.search(rf"(?m)^(async )?(def|class) {name}\b", w)), ""
      )
    else:
      text = name in here and (got := literal(here[name])) and f"{name} = {got}"
    if not text:
      raise Refused("no dump of " + name)
    out[text] = name
  return "\n".join(out)


def standing():
  return answer("stand", ROOT, [])


def automatic():
  models = [one for one in (standing()[:1] or [[]])[0] if one[0] != OPERATOR]
  placed = {}
  for entry in models:
    isinstance(place := (entry[4:] or [None])[0], int) and placed.setdefault(place, entry[0])
  return next(iter([placed[k] for k in sorted(placed)] + [two[0] for two in models if two[3:4] == ["cheap"]]), "")


def operated(where):
  return where.split("/")[0] == OPERATOR


def stand(on=""):
  isinstance(got := peek(a := act("stand", on, None)), list) and tell(on, roster=got[0], actor=got[2])
  return a


def clock(on="") -> float:
  return ask("clock", on)


def chance(on="") -> float:
  return ask("chance", on)


def gate(word: str, on="") -> list[str]:
  return ask("gate", on, unquoted(word))


def cd(path: str, on=""):
  path = ask("cd", on, path)
  tell(on, path)
  return path


def cwd(on="") -> str:
  return answer("cd", on, "")


def pause(id: str, why=None):
  if question(("rung", who := acting())) and covers(("pause", id), who):
    raise Refused(f"{who} cannot pause itself through {id}")
  control("pause", "paused", id, why)


def wake(id: str):
  control("wake", "woke", id)


def cancel(id: str, why=None):
  control("cancel", "cancelled", id, why)


def close(value: object, id=""):
  match get(who := acting()):
    case ("rung", _, by, _, _, back, *_):
      if back:
        raise CancelledError()
      id = id or by * prompted(by)
  match get(id := id or who):
    case ("prompt", _, _, on, shape, *_) if not isinstance(value, BaseException):
      try:
        s = eval(shape, module(on)) or object
        assert any(
          value in [a for a in x.__args__ if type(a) is type(value)]
          if (origin := getattr(x, "__origin__", x)) is Literal
          else isinstance(value, origin)
          for x in (s.__args__ if isinstance(s, type(int | str)) else [s])
        )
      except Exception:
        raise Refused(repr(value) + " not " + shape) from None
  control("close", "closed", id, value)
  if under(who, id):
    raise CancelledError()


def debug(template: Template):
  text = "".join(
    x if isinstance(x, str) else format(("%" + x.conversion) % (x.value,) if x.conversion else x.value, x.format_spec)
    for x in template
  )
  (who := acting()) and tells(who) and text and say(*told(who, "debugged", debug=text))


def wait(seconds: float = 0, *acts: str, on="") -> Act[str | None]:
  if not acts:
    raise Refused("no act: await the act, or wait(seconds, act)")

  def ear(id):
    while not (got := list(filter(over, acts))):
      yield {id, *acts}
    yield "done", id, got[0]

  return act("wait", on, controlled(ear), seconds, *acts)


def rung(word="", retells="", to="", on="") -> Act:
  def ear(id):
    yield "started", id
    mine = {retells, scope(id)}
    if word:
      while (c := crafted(id)) and c[0] not in lineage(id):
        yield {"rung"}
      if to:
        act("reply", "", lambda r: (yield "done", r, ("assistant", word, None, None)), to)
      elif tells(id):
        yield "tell", id, [word]
      while not over(retells) and get(retells) if retells else paused(get(id)[2]):
        yield mine
      yield "ready", id, word
    while True:
      match (yield mine):
        case ("done", about, _, value) if question(("reply", about)) and get(about)[2] == id and not word:
          yield ("done", id, value) if isinstance(value, BaseException) else ("ready", id, value[1])
        case ("wants", about, by, _, call) if get(by)[4] == id:
          yield "started", about
          while not over(call):
            yield {call}
          yield "done", about, peek(call)
        case ("done", about, _, value) if question(("run", about)) and get(about)[4] == id:
          if isinstance(value, CancelledError):
            if retells:
              value = None
            elif tells(id):
              yield told(id, "cancelled")
          elif isinstance(value, BaseException):
            module()["raised"] = value
            if tells(id):
              yield told(id, "raised", raised=value)
          yield "done", id, value

  return act("rung", on, controlled(ear), word, retells, to if word or to else module(on).get("actor", ""))


def prompt[T](shape: type[T] | object, message="", to="", on="") -> Act[T]:
  named = (
    shape if isinstance(shape, str) else re.sub(r"""<class '|'>|('[^']*'|"[^"]*")|[\w.:/]*\.""", r"\1", repr(shape))
  )
  thread = on * prompted(on)
  to = to or (thread and get(thread)[6])
  asks = (to or module(on).get("actor")) != OPERATOR
  says = asks and thread and named == "None" and not over(thread)

  def ear(id):
    if asks:
      yield "started", id
      while crafted(id):
        yield {"rung"}
    yield opened(id, named, message=message, thread=thread)
    a: tuple = ()
    while not says:
      got = a[:1] == ("done",) and get(a[1])
      heard = got and prompted(a[1]) and got[3:5] == (id, "None")
      heard or (
        got
        and got[2] == id
        and (
          owed := (
            "",
            *[
              x[1] * operated(x[2])
              for x in transcript(id)
              if (x[3:5] == (id, "None") and operated(x[2]))
              or (x[0] == "prompt" and x[6] == OPERATOR and under(x[2], id))
              or (x[:3:2] == ("rung", id) and not over(x[1]))
            ],
          )[-1]
        )
        and prompt(None, owed + " unanswered", on=id)
      )
      asks and not (
        paused(id)
        or any(
          id in x[2:4] and not over(x[1]) and not (heard and any(y[2] == x[1] for y in transcript(id, "reply")))
          for x in transcript(id, "rung")
        )
      ) and rung(to=to)
      a = yield {id}
    yield "done", id, None

  return act("prompt", on, controlled(ear), named, message, to)


def chain(label="", source="", filter: Filter | None = None, on="") -> Act[Never]:
  if scope(source) != source:
    raise Refused("no chain " + source)

  def ear(id):
    t = transcript(source or ROOT)
    h = [(x[0] == "tell" and x[3][0][:6]) or x[0] for x in t] + ["chain(", "#chain", "setup"]
    hi = h.index("#chain", lo := h.index("chain("))
    blocked, running, waiting, last, heard, seen = set(), {}, {}, standing(), [], set()
    step = news = ran = reply = note = to = mute = ""
    stood = module(source or get(id)[3]).get("actor", last and last[2])

    def placed(went):
      return rung("stand()" + (went and "\ncd(" + repr(went) + ")"), to=stood)

    def bind(whose):
      w = "\n\n".join(heard)
      heard.clear()
      return w and act("run", id, None, n := whose + "_told", unquoted(ladder.setdefault(n, w)), "")

    def replay(of="", words=""):
      fresh = not of
      for whose, said in list(ladder.items()):
        if under(whose, of):
          if (words + "\n").startswith(said + "\n"):
            words = words[len(said) + 1 :]
          else:
            fresh |= whose not in blocked
            del ladder[whose]
            cancel(whose)
      if fresh:
        yield "module", id, {**globals(), "__name__": id, "actor": stood}
        for whose, said in ladder.items():
          whose in blocked or (said and rung(said, whose))
      if words:
        with site.set(of):
          rung(words)

    if source or t[lo:hi]:
      kin = {source, *[n for one in (filter or list)([x for x in t if question(x)]) for n in lineage(one[1])]}
      later = {x[1] for x in t[h.index("setup") :] if question(x) and (not get(x[2]) or x[:3:2] == ("rung", ROOT))}
      later |= {x[1] for x in t if x[0] == "run" and not later.isdisjoint(lineage(x[4]))}
      yield (
        "prefix",
        id,
        [
          it
          for n, it in enumerate(t)
          if (lo <= n < hi and later.isdisjoint(lineage(it[1])))
          or (source and (not (b := get(it[1])) or (b[2] if b[0] == "reply" else it[1]) in kin))
        ],
      )
    ladder = {x: w for x, w in program(source or id).items() if over(x) or not get(x)}
    yield "started", id

    def opening():
      return opened(
        id,
        "Never",
        label=label,
        source=source,
        actor=stood * (not source),
        actor_via=(not source) * (get(id)[3] or "stand") or None,
      )

    top = opening()
    if last and (source or not last[3:]):
      yield top
      top = ""
    yield from replay()
    seat = top and last and placed(last[1])
    while True:
      r = get((a := (yield {id, "stand", "reply"}))[1]) or a
      match a:
        case ("prefix", _, by, _) if by != id:
          top = ""
        case ("done", *_) if r[0] == "stand" and standing() != last:
          was, last = last, standing()
          if last[2:3] != was[2:3]:
            stood = module()["actor"] = last[2]
            top = top and opening()
          if not was:
            yield ("tell", id, ["chain()"]) if last[3:] else top
            top *= bool(last[3:])
            if last[4:] and id == ROOT and not transcript(id, "reply") and not transcript(id, "carried"):
              yield from seeded(id, last, stood)
          elif last[3:] and not top:
            placed(last[1] * (was[1] != last[1]) * all(all(get(x[2])[4::2]) for x in transcript(id, "cd")))
        case ("done", about, _, value) if running.get(maker := r[2]) in (
          False,
          isinstance(value, Exception) and r[0] != "reply" and "",
        ) and repr(about) not in str(
          transcript(id, "wants") + [x[1] for x in transcript(id, "close") if scope(x[2]) == id != x[2]]
        ):
          scope(about) != id and (yield "tell", maker, [headed(about, "done", value=value)])
          value is None or isinstance(value, CancelledError) or (
            news := (about + " done", maker, isinstance(value, Exception))
          )
        case ("done", _, by, Refused() as why) if (
          r[0] == "reply"
          and r[3] != id
          and (paused(r[3]) or not by)
          and (maker := (get(p := get(r[2])[2]) or a)[2]) in running
        ):
          yield "tell", maker, [headed(p, "paused", why=why)]
          running[maker] or (news := (p + " paused", maker, 0))
        case (kind, about, by, *_) if (
          ((kind == "started" and not get(by)) or kind == "prompt") and r[2] in running and not get(r[2])[4]
        ):
          seen.add(about)
      if scope(a[1]) != id:
        continue
      if a[0] in ("ready", "done"):
        waiting.pop(a[1], None)
      match a:
        case ("read", about, by, _, path) if prompted(path) and scope(path) == id:
          yield "done", about, Text(path, "\n".join(w for x, w in ladder.items() if x != by and under(x, path)))
        case ("write", about, by, _, Text(path, content) as text) if prompted(path) and scope(path) == id:
          under(by, path) and ladder.pop(by, None)
          yield from replay(path, content.rstrip("\n"))
          yield "done", about, text
        case ("read", about, *_, path) if (door := re.fullmatch(r"(bash\d+)/(stdout|stderr)", path)) and get(door[1]):
          yield (
            "done",
            about,
            getattr(
              peek(door[1]),
              door[2],
              Text(path, "".join(x[3] for x in transcript(door[1], "out") if x[1::3] == door.groups())),
            ),
          )
        case ("done", *_) if top and r[0] == "rung" and not crafted(id):
          if seat:
            yield top
            top = ""
          else:
            seat = placed(last[1])
        case ("rung", rid, _, _, "", *_):
          waiting[rid] = running[rid] = ""
        case ("tell", *_, notes) if notes not in (["chain()"], [*r[4:5]]):
          heard.append("\n".join(notes))
          ran = mute = ""
          if a is note:
            note = bind(step)
        case ("done", about, *_) if about == note:
          with site.set(step):
            reply = act("reply", id, controlled(idle), to)
        case ("ready", rid, _, word):
          try:
            rid == step or bind(rid)
            ladder[(donor := r[5]) or rid] = word
            found = (ran := tells(rid) and rid) and gate(word)
            if not found:
              running[rid] = act("run", id, None, rid, unquoted(word), donor)
          except Refused as e:
            found = [str(e)]
          if found:
            yield told(rid, "refused", findings="\n".join(found))
            blocked.add(rid)
            close(Refused(*found), rid)
        case ("done", _, "", Refused() as why) if r[0] == "reply":
          pause(id, why)
      if r[0] == "run":
        running[r[4]] = a[0] != "done"
        a[0] == "done" and (mute := (get(r[4]) or a)[2] * (repr(a[1]) not in str(transcript(id, "wants"))))
      elif r[0] == "wants":
        running[get(r[2])[4]] = a[0] != "started"
      a[0] == "done" and a[1] in seen and (mute := "")
      if any(running.values()):
        continue
      waits = [c for *_, c in transcript(id, "wants") if not over(c)]
      if step not in waiting and (
        step := next(
          (x for x in waiting if not (paused(x) or over(x) or (mute == get(x)[2] and not all(map(over, seen))))), ""
        )
      ):
        maker, to = get(step)[2::4]
        if offered(last[0], to) is None:
          close(Refused(to + " no actor"), maker * prompted(maker) or step)
        else:
          if ran:
            yield told(ran, "told nothing")
          note = yield told(step, "advance on " + maker, share=filled(reply) or None, waits=waits or None)
          news = ""
      if news and not waiting and (r[2] in running or over(r[2]) or a[0] == "tell"):
        ours = get(news[1])[2]
        prompted(ours) and (news[2] or not over(ours)) and prompt(None, news[0], on=ours)
        news = ""

  return act("chain", on, ear, label, source)


def seeded(id, last, to):
  rung('debug(t"{standing()[4]=}")', to=to)
  rung(f"read({last[3]!r})", to=to)
  for k in 0, 1:
    k and (yield "setup", id)
    for x in last[4]:
      x[1] and x[3] == k and rung(f"rung(read({x[1]!r}, HIDDEN).content)", to=to)
    (w := "\n".join(y[2] for y in last[4] if y[3] == k and y[2])) and rung(w, to=to)


HEARD = (
  "say('prefix', scope(acting()), [*transcript(of='module')[-1:], *transcript(of='carried')[-1][3], "
  "*transcript(of='stand')[-1:], *transcript(of='pause'), *[x for x in transcript() if acting() in x[1::3]]])"
)


def seed(data):
  entries, numbers = [], Counter()

  def put(sort, called, *words):
    last = int(called[len(sort) :])
    entries.extend(((sort, f"{sort}{n}", ROOT, ""),) for n in range(numbers[sort] + 1, last))
    numbers[sort] = max(numbers[sort], last - 1) + bool(words)
    words and entries.append(((sort, called, *words),))

  for c in data["chains"]:
    put("chain", c["id"], OPERATOR, c["on"], c["label"], "")
    entries.append((("carried", c["id"], "journal", c["turns"]),))
    c["paused"] and entries.append((("pause", c["id"], OPERATOR),))
  for x in data["acts"]:
    "value" in x or put("prompt", x["id"], OPERATOR, x["on"], x["shape"], x["message"], x["to"])
    "value" in x or (x["held"] and entries.append((("started", x["id"], x["held"]),)))
  for kind, most in data["taken"].items():
    put(kind, f"{kind}{most + 1}")
  for x in data["acts"]:
    i = x["id"]
    "value" in x and entries.extend(
      [((x["kind"], i, "journal", x["on"]),), (("started", i, "journal"),), (("done", i, "journal", x["value"]),)]
    )
  for c in data["chains"]:
    i, cut = c["id"], c["cut"] + [y["rung"] for y in c.get("again", ())]
    word = "\n".join(
      [
        c["definitions"],
        *(f"{named} = {text}" for named, text in c["values"].items()),
        HEARD,
        f'debug(t"The life goes on from a checkpoint. It lost {c["lost"] or "no name"}, and it cut {cut or "no act"}.")',
      ]
    ).strip()
    put("rung", f"rung{numbers['rung'] + 1}", OPERATOR, i, word, "", "")
    put("gate", gated := f"gate{numbers['gate'] + 1}", i, i, word)
    entries.append((("done", gated, "gate", []),))
  return entries


def gathered(define, floor):
  def number(called):
    return int(re.sub("^[a-z_]+", "", called) or 0)

  chains = []
  while get(f"chain{len(chains) + 1}"):
    chains.append(f"chain{len(chains) + 1}")
  asked = [get(h) for h in chains] + [x for h in chains for x in transcript(h) if question(x) and x[0] != "chain"]
  asks = [x[1] for x in asked if x[0] == "prompt" and not over(x[1])]
  cut = sorted((x[1] for x in asked if x[0] == "run" and not over(x[1]) and get(x[4])), key=number)
  gone = {x[4] for x in asked if x[0] == "wants" and x[2] in cut and prompted(x[4]) and not over(x[1])}
  asks = [x for x in asks if x not in gone]
  live, values, lost, named = {ROOT, *map(scope, asks)}, {}, {}, set(asks)
  while live - values.keys():
    for c in sorted(live - values.keys(), key=number):
      here, values[c], lost[c] = module(c), {}, []
      for key, value in here.items():
        if not (key.startswith("__") or callable(value) or globals().get(key, here) is value):
          found = set()
          if text := literal(value, found):
            values[c][key] = text
            named |= found
          else:
            lost[c].append(key)
    live |= {*map(scope, named)}
  live = sorted(live, key=number)
  taken = dict(floor)
  for one in asked:
    taken[one[0]] = max(taken.get(one[0], 0), number(one[1]))
  verbs = ("prompt", "bash", "read", "write", "wait", "cd", "chance")
  done = {x[1] for x in asked if x[0] == "bash" and scope(x[1]) in live}
  borne = sorted((x for x in named | done if get(x)[0] in verbs), key=lambda r: (get(r)[0], number(r)))
  stands = [x[1] for x in transcript(ROOT, "stand") if question(x) and over(x[1])][-1:]
  ticks = [x[1] for x in transcript(ROOT, "clock") if question(x) and isinstance(peek(x[1]), float)][-1:]
  acts, asking = [], {scope(x) for x in borne if prompted(x)}
  for one in [*stands, *ticks, *borne]:
    a = get(one)
    d = {"kind": a[0], "id": one, "on": a[3]}
    if prompted(one) and not over(one):
      held = next((x[2] for x in transcript(scope(one), "started") if x[1] == one and get(x[2]) is None), "")
      acts.append({**d, "shape": a[4], "message": a[5], "to": a[6], "held": held})
    elif over(one):
      literal(peek(one), set()) and acts.append({**d, "value": peek(one)})
    else:
      cut.append(one)
      cmd = a[4] if a[0] == "bash" else ""
      why = (
        '"'
        + cmd.replace("\\", "\\\\").replace('"', '\\"')
        + '" was interrupted: the life that ran it ended before it did'
      )
      acts.append({**d, "value": Refused(why if cmd else one + " was cut by the checkpoint")})
  out = []
  for c in live:
    a = get(c)
    saved = [
      x
      for x in transcript(c)
      if x[0] not in ("module", "carried")
      and literal(x, set())
      and (not question(x) or x[0] == "reply" or x[1] in borne)
    ]
    held = {ROOT, *live, *borne, *(x[1] for x in saved if question(x))}
    out.append(
      {
        "id": c,
        "on": a[3] if a[3] in live else "",
        "label": a[4],
        "source": a[5],
        "paused": c in asking or paused(c),
        "turns": [x for x in saved if x[0] not in ("started", "done") or x[1] in held],
        "definitions": "\n\n".join(
          filter(None, [define(w) for r, w in program(c).items() if (get(r) or [0] * 3)[2] != "extensions"])
        ),
        "values": values[c],
        "lost": lost[c],
        "cut": [x for x in cut if scope(x) == c],
      }
    )
  return {"taken": taken, "chains": out, "acts": acts}


def grant(usd: float | None = None, share: float | None = None, on="") -> Act[None]:
  def ear(id):
    here = scope(id)
    if not ((usd or share) and (usd or 0) >= 0 <= (share or 0) <= 1):
      yield "done", id, Refused(f"{usd}/{share} no ceiling")
      return
    yield "started", id
    spent = 0
    for x in transcript(here, "grant"):
      x[3] != here or x[1] == id or close(None, x[1])
    yield opened(id, "None", usd=usd, share=share)
    while True:
      match (yield {id, here}):
        case ("done", about, _, (_, _, (*_, cost), _)) if question(("reply", about)):
          spent += cost
          yield told(id, "ledger", spent=spent)
          if (usd and spent >= usd) or (share and filled(about) >= share):
            pause(here, "ceiling")

  return act("grant", on, controlled(ear), usd, share)


def bash(
  command: str, stdin: str | None = "", timeout=TIMEOUT, ok=None, show: Show = TAIL, show_err: Show | None = None, on=""
) -> Act[Exit]:
  def ear(id):
    yield opened(id, "Exit", command="" if show is HIDDEN else command)
    while True:
      match (yield {id, "merged"}):
        case ("merged", qid, *_, about) if about == id:
          yield "done", qid, show_err is None
        case ("done", about, _, got) if about == id:
          match got:
            case Exit(code, out, err) if show is not HIDDEN:
              yield told(
                id,
                f"timed out after {timeout}s" if code is None else f"exited {code}",
                stdout=cut(shown(out, show)),
                stderr=show_err and cut(shown(err, show_err)),
              )
          return

  def cut(text, most=LARGEST // 16):
    return text if len(text) <= 2 * most else text[:most] + f"\n... ({len(text)} chars)\n" + text[-most:]

  return act("bash", on, controlled(ear, True), command, stdin, timeout, ok)


@dataclass
class Text:
  path: str
  content: str = ""
  before = None

  @property
  def lines(self) -> list[str]:
    return self.content.splitlines()

  def edit(self, lo: int, hi: int, text: str) -> Text:
    now = (self.content + "\n").splitlines(True)[: len(self.lines)]
    if not 1 <= lo <= hi + 1 <= len(now) + 1:
      raise Refused(f"{self.path} no lines {lo}:{hi}")
    now[lo - 1 : hi] = [text and text.removesuffix("\n") + "\n"]
    return self.replace(self.content, "".join(now))

  def replace(self, old: str, new: str, count=-1) -> Text:
    if old not in self.content:
      raise Refused(self.path + " no " + repr(min(old.splitlines(), key=self.content.count)))
    (made := Text(self.path, self.content.replace(old, new, count))).before = self
    return made

  def undo(self, n=1) -> Text:
    for _ in range(n):
      self = self.before or self  # noqa: PLW0642
    return self

  def append(self, text: str) -> Text:
    return self.insert(len(self.lines) + 1, text)

  def insert(self, line: int, text: str) -> Text:
    return self.edit(line, line - 1, text)

  def delete(self, lo: int, hi: int) -> Text:
    return self.edit(lo, hi, "")


@dataclass
class Exit:
  code: int | None
  stdout: Text
  stderr: Text


class Act[T = object](str):
  def __await__(self) -> Generator[object, Any, T]:
    if (acting() and question(("chain", self))) or not get(self):
      raise Refused(self + " never settles")
    if who := acting():
      if not over(self) and (self == who or (question(("run", self)) and get(self)[4] == who)):
        raise Refused(f"{who} cannot await its own completion through {self}")
      return (yield self)
    f = get_running_loop().create_future()

    def pend():
      while not over(self):
        yield
      (f.set_exception if isinstance(got := peek(self), BaseException) else f.set_result)(got)

    drive(g := pend(), self + " waits " + str(id(g)))
    try:
      return (yield from f)
    finally:
      g.close()


class Refused(Exception): ...


class Drift(Exception): ...


def lineage(name):
  yield name
  while a := get(name):
    yield (name := a[2])


def under(name, of):
  return "" != of in lineage(name)


def acting():
  return site.get() * bool(get(site.get()))


def prompted(name):
  return question(("prompt", name))


def question(a):
  return bool(re.fullmatch(a[0] + r"\d+", a[1]))


def scope(name):
  while (a := get(name)) and a[0] != "chain":
    name = a[3]
  return name * bool(a)


def tell(on, path="", got=None, show=HEAD, **words):
  (who := acting()) and tells(who) and say(
    *told(
      transcript(on, who)[-1][1],
      path=path,
      **words,
      **{"numbers": at if (at := show(got.lines)) and at[-1] - at[0] >= len(at) else None, "text": shown(got, show)}
      if isinstance(got, Text)
      else {"value": got},
    )
  )


def answer(kind, on, empty):
  return next((got for x in reversed(transcript(on, kind)) if isinstance(got := peek(x[1]), type(empty))), empty)


def filled(about):
  match peek(about):
    case (_, _, (tokens, *_), _):
      return round(tokens / (offered(standing()[0], get(about)[4]) or WINDOW), 2)


def over(id):
  return peek(id, ...) is not ...


def tells(id):
  return get(id)[2] != scope(id) or all(get(id)[4::2])


def crafted(id):
  return [x[1] for x in transcript(id, "rung") if all(x[4::2]) and not over(x[1])]


def told(id, what="", *notes, **words):
  return "tell", id, [headed(id, what, **words), *notes]


def control(kind, name, id, *words):
  if not get(id):
    raise Refused("no act " + repr(id))
  over(id) or scope(acting()) == scope(id) or say(*told(id, name + " by " + site.get(), value=(*words, None)[0]))
  return say(kind, id, *words)


def headed(id, what="", **words):
  text = f"#{id} {what}".rstrip()
  for word, value in words.items():
    name = id + "_" + word
    if isinstance(value, str) and "\n" in value:
      while "</s:" + name + ">\n" in value + "\n":
        name += "_"
      text += f"\n<s:{name}>\n{value}</s:{name}>"
    elif value not in (None, ""):
      text += f"\n{name} = " + re.sub(r"^[\w.]+\.(?=[A-Z]\w*\()", "", repr(value))
  return text


def opened(id, of, **words):
  return told(id, "", id + ": Act[" + of + "] = Act(" + repr(id) + ")", **words)


def shown(text, show):
  lines = text.lines
  return "\n".join(x[:1000] + f"... ({len(x)} chars)" if (x := lines[i - 1])[1000:] else x for i in show(lines))


def unquoted(word):
  made, at, odd = [], 0, set()
  for o in re.finditer(r"(?m)^<s:(\w+)>\n?", word):
    if o.start() >= at and o[1] not in odd:
      if m := re.compile("(?m)</s:" + o[1] + ">$").search(word, o.end()):
        made += [
          word[at : o.start()],
          o[1] + " = " + repr(word[o.end() : m.start()]) + "\n" * word.count("\n", o.start(), m.end()),
        ]
        at = m.end()
      else:
        odd.add(o[1])
  return "".join(made) + word[at:]


def offered(roster, to):
  return next((x[2] for x in roster if to in (x[0], *[x[0] + "/" + e for e in x[1]])), None)


def covers(a, id):
  kind, of, *_ = a

  def on(name):
    while name != of and prompted(name):
      name = get(name)[3]
    return name == of

  if kind == "close":
    if question(("reply", id)):
      id = get(id)[2]
    return on(id) or (question(("rung", id)) and on(get(id)[2]))
  return any(map(on, lineage(id))) or scope(id) == of


def paused(id):
  return next((x[0] == "pause" for x in reversed(transcript(id, "pause")) if covers(x, id)), False)


def idle(id):
  while True:
    yield {id}


def lives(g, a):
  try:
    while isinstance(a := g.send(a), tuple):
      a = say(*a)
  except StopIteration:
    return False
  return a


def controlled(ear, lasting=False):
  def lived(id):
    g, later, halt = ear(id), [], paused(id)
    w = lives(g, None)
    while w is not False:
      a = later.pop(0) if later and not halt else (yield w)
      if over(id) and not lasting:
        return
      match a:
        case ("pause" | "wake", *_) if covers(a, id) and (halt := a[0] == "pause"):
          pass
        case ("cancel" | "close", _, by, *_) if covers(a, id) and not (over(id) or (halt and under(by, id))):
          yield (
            "done",
            id,
            CancelledError(*filter(None, a[3:])) if a[0] == "cancel" else a[3] if a[1] == id else CancelledError(),
          )
        case _ if halt and get(a[1]) is not a:
          later.append(a)
        case _:
          w = lives(g, a)

  return lived


def boot(record=(), **outside):
  global say, act, drive, get, peek, transcript
  get_running_loop()
  made, known, done, held, log, alive, born, busy, left, heed = Counter(), {}, {}, {}, [], {}, {}, set(), [], {}
  first, owned, taken = {e[1]: e for (e,) in record[::-1] if e[0] in ("started", "done")}, set(), {}
  due = [e for (e,) in record[::-1] if first.get(e[1]) is not e]
  saved, again, stalled = {e[1]: e for (e,) in record if question(e)}, {}, []

  def drift(name):
    return Drift(
      f"{name} drifts: the life made {get(name)!r:.300}, the record holds {saved.get(name) or first.get(name)!r:.300}"
    )

  def owed():
    while due and question(due[-1]) and due[-1][1] in known:
      due.pop()
    return due

  def repeat(kind, about, by, *words):
    with site.set(by):
      a = say(kind, about, *words)
    again[id(a)] = a
    held.setdefault((scope(about), "journal"), []).append(a)

  def recount(entry):
    match entry:
      case (kind, name, by, on, *words) if question((kind, name)):
        if (
          by in saved
          or (on and not get(on))
          or (by == "journal" and not holds(scope(on), [known.setdefault(name, (kind, name, by, on))]))
        ):
          born.setdefault(kind, {})[name] = name
          return None
        if by not in outside and (
          not callable(verb := (module(on) or globals()).get(kind)) or re.fullmatch(r"\w+?\d+", by)
        ):
          raise drift(name)
        with site.set(by):
          try:
            act(kind, on, None, *words) if by in outside else verb(*words, on=on)
          except Refused:
            pass
          except (Exception, CancelledError) as fault:
            if not get(name) or isinstance(fault, Drift):
              raise
            return fault
      case (_, about, *_) if scope(about):
        repeat(*entry)
    return None

  def journal(a=(), last=None):
    try:
      while True:
        while owed() and (
          (stalled and stalled.pop())
          or not (log or left)
          or (due[-1][0] == "joined" and not question(due[-2]) and due.pop() and due)
          or (a and a[::2] == ("wake", "journal") and due[-1][1] in taken)
        ):
          if fault := recount(due.pop()):
            stalled.append(fault)
        b = a
        match a := (yield):
          case (kind, about, by, *_) if (
            (q := get(about)) and by != "journal" and (by or repr(first.get(about)) != repr(a))
          ):
            if not by and a != q and (owed() or about in first):
              raise drift(about)
            if by not in known and by not in owned:
              glue = (
                b is last is not None
                and kind not in ("started", "done")
                and ("keep", "", (("joined", "", "journal", kind, about),))
              )
              if about not in saved:
                a is q and glue and (yield glue)
                yield "keep", "", (saved.setdefault(about, q),)
              if a is not q:
                glue and (yield glue)
                yield "keep", "", (a,)
              last = a
            if kind == "wake" and not owed():
              for name in [x for x in taken if taken[x] and covers(a, x) and not over(x)]:
                del taken[name]
                offers(known[name])
    finally:
      for pile in log, left, due, first, saved:
        pile.clear()

  def say(kind, about, *words):
    a = (kind, about, site.get(), *words)
    if about in known and kind in ("started", "done"):
      taken.setdefault(about, False)
      kind == "done" and done.setdefault(about, words[0])
    kind == "prefix" and [held[x].clear() for x in held if x[0] == about]
    holds(scope(about), words[0] if kind == "prefix" else [a])
    log.append((a, ()))
    dispatch()
    return a

  def act(kind, on, ear, *words):
    speaker = site.get()
    made[speaker, kind] += 1
    by = (question(("rung", speaker)) and known[speaker][5]) or speaker
    on = on or scope(speaker)
    if not on and kind != "chain":
      raise Refused("no chain for " + kind)
    names = born.setdefault(kind, {})
    a = (kind, name := names.setdefault((by, made[speaker, kind]), kind + str(len(names) + 1)), by, on, *words)
    if known.setdefault(name, a) is a:
      holds(scope(on), [a])
      log.append((a, heard := set(outside) - busy))
      busy.add(id(a))
      try:
        for n, g in ears(a):
          ear or n in heard or n == "journal" or n in busy or name in taken or hear(n, g, a) or heard.add(n)
        if ear:
          heard.add(name)
          drive(ear(name), name)
        if saved.get(name, a) == a:
          if name not in taken and (f := first.get(name)):
            taken[name] = f[0] == "started"
            repeat(*f)
            while taken[name] and owed() and due[-1][0] == "joined" and due.pop() and due:
              recount(due.pop())
          if kind in ("run", "chain") or not owed():
            offers(a)
        if name not in taken and not busy & set(outside) & set(dict(ears(a))):
          with site.set(""):
            say("done", name, Refused("nothing takes " + kind))
      finally:
        busy.discard(id(a))
      dispatch()
    return Act(name)

  def offers(a):
    for n, g in outside.items():
      (a[1] in taken and a[0] != "chain") or hear(n, g, a)

  def ears(a):
    q = get(a[1]) or a[:1] * 4
    k = {a[0], *q[:4], *map(scope, q[2:4])}
    return sorted(
      (x for x in alive.items() if k & (heed.get(x[0]) or k) or a[0] in ("pause", "wake", "cancel", "close")),
      key=lambda x: (x[0] not in known, x[0] in outside),
    )

  def holds(on, facts):
    for x in on and facts:
      for k in {"", x[0].replace("wake", "pause"), x[2]}:
        held.setdefault((on, k), []).append(x)

  def dispatch():
    while not busy:
      if left:
        name, g, a = left.pop(0)
        try:
          hear(name, g, a)
        except (Exception, CancelledError) as fault:
          if name == "journal" or isinstance(fault, Drift) or stalled is None:
            raise
          stalled.append(fault)
          hear("journal", alive["journal"], None)
      elif log:
        a, heard = log.pop(0)
        left.extend((*x, a) for x in ears(a) if x[0] not in heard)
      elif ((g := alive.get("journal")) and hear("journal", g, None)) or not log:
        return

  def hear(name, g, a):
    if name not in busy and alive.get(name) is g:
      with site.set(name):
        busy.add(name)
        try:
          heed[name] = w = lives(
            g, (*a[:2], "journal", *a[3:]) if again.get(id(a), 0) is a and a[2] and name not in known else a
          )
          w is False and alive.pop(name)
        finally:
          busy.discard(name)

  def drive(g, name):
    if name in alive:
      raise Refused(name + " hears")
    acting() and owned.add(name)
    alive[name] = g
    hear(name, g, None)
    dispatch()

  def get(about):
    return known.get(about)

  def peek(at, waiting=None):
    return done.get(at, waiting)

  def transcript(on="", of=""):
    return held.get((scope(on or site.get()), of), [])[:]

  for who, listener in [(OPERATOR, idle(OPERATOR)), *outside.items(), ("journal", journal())]:
    drive(listener, who)
  stalled = None
  root = Act(ROOT) if known else chain("root")
  stand(ROOT)
  return root

CAP = 40
BUDGET = 4096


def catchup(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here = scope(id)
    if here == ROOT:
      act("clock", here, None)
    while True:
      match (yield {id, "stand"}):
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          if here == ROOT:
            act("clock", here, None)
          seen: dict[str, object] = {}
          for fact in transcript(here)[::-1]:
            if fact[0] not in ("read", "write") or (fact[0] == "read" and str(fact[4]).endswith(("/", "\\"))):
              continue
            was = peek(fact[1])
            path = was.path if isinstance(was, Text) else str(fact[4])
            if path in seen:
              continue
            seen[path] = None
            if isinstance(was, Text) and "://" not in path and get(path.split("/")[0]) is None:
              try:
                now = read(path, HIDDEN, here).lines
              except Refused:
                seen[path] = "gone"
                continue
              lines = {i: now[i - 1] for i in differs(was.lines)(now)}
              lines |= dict.fromkeys(range(len(now) + 1, len(was.lines) + 1))
              seen[path] = len(lines) if len(lines) > CAP else lines or None
          clocks = [x for one in transcript(ROOT, "clock") if isinstance(x := peek(one[1]), float)][-2:] or [0.0]
          hours = (clocks[-1] - clocks[0]) / 3600
          changed: dict | list = {key: value for key, value in seen.items() if value}
          kept = len(changed)
          while True:
            paragraph = headed(here, "caught up", hours=round(hours, 1) if hours > 1 else None, changed=changed or None)
            if len(paragraph.encode()) <= BUDGET:
              break
            changed = [*changed][:kept]
            kept -= 1
          if "\n" in paragraph:
            yield "tell", here, [paragraph]

  return act("catchup", on, ear)

NAMES = ("AGENTS.md", "CLAUDE.md")
LOCAL = ("AGENTS.local.md", "CLAUDE.local.md")


def lacking(known: set[str]) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if line not in known]


def remembered(path: str) -> bool:
  return path.replace("\\", "/").rsplit("/", 1)[-1] in (*NAMES, *LOCAL)


def joined(folder: str, name: str) -> str:
  return folder + name if folder.endswith(("/", "\\")) else folder + "/" + name


def looked(path: str, on: str = "") -> Text | None:
  try:
    return read(path, HIDDEN, on)
  except Refused:
    return None


def pieces(path: str) -> list[str]:
  kept: list[str] = []
  for one in path.replace("\\", "/").split("/"):
    if one == ".." and kept and kept[-1] not in ("", ".."):
      kept.pop()
    elif one not in (".", "") or not kept:
      kept.append(one)
  return kept


def folders(path: str = ".", on: str = "") -> list[Text]:
  up: list[Text] = []
  at = "./"
  while (got := looked(at, on)) is not None and not (up and got.path == up[-1].path):
    up.append(got)
    at = joined(got.path, "../")
  down: list[Text] = []
  if up and "://" not in path:
    here = pieces(up[0].path)
    absolute = path.startswith(("/", "\\", "~")) or path[1:3] in (":/", ":\\")
    full = pieces(path if absolute else joined(up[0].path, path))
    held = up[0]
    for one in full[len(here) :] if full[: len(here)] == here else []:
      if one + "/" not in held.lines or (deeper := looked(joined(held.path, one + "/"), on)) is None:
        break
      down.append(held := deeper)
  user = looked("config://", on)
  return [*([user] if user else []), *up[::-1], *down]


def memory(path: str = ".", on: str = "") -> list[Text]:
  was: dict[str, list[str]] = {}
  held: set[str] = set()
  for x in transcript(on):
    match x:
      case ("done", about, _, Text(place, content)) if (
        (question(("read", about)) or question(("write", about))) and get(maker := get(about)[2]) and tells(maker)
      ):
        was[place] = content.splitlines()
        if remembered(place):
          held.add(content)
  got: list[Text] = []
  for folder in folders(path, on):
    names = set(folder.lines)
    for group in NAMES, LOCAL:
      name = next((one for one in group if one in names), "")
      if not name or (found := looked(joined(folder.path, name), on)) is None:
        continue
      if found.content in held or any(one.path == found.path or one.content == found.content for one in got):
        continue
      got.append(found)
      mine = set(found.lines)
      near = max(was.values(), key=lambda kept: len(set(kept) & mine), default=[]) if found.path not in was else []
      if found.path in was:
        show = differs(was[found.path])
      elif mine and 2 * len(set(near) & mine) > len(mine):
        show = lacking(set(near))
      else:
        show = span(1, -1)
      tell(on, found.path, found, show)
  return got


async def recall(on: str = "") -> Act:
  return remember(on)


def remember(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    before = {x[1] for x in transcript(on, "read")}
    memory(on=on)
    while True:
      match (yield {id, "read", "stand"}):
        case ("done", about, _, Text(path)) if (
          question(("read", about))
          and scope(about) == scope(id)
          and "://" not in path
          and about not in before
          and question(("rung", (made := get(about))[2]))
          and not str(made[4]).endswith(("/", "\\"))
          and not remembered(path)
        ):
          memory(path, on)
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          memory(on=on)

  return act("remember", on, controlled(ear))

def skills(on: str = "") -> Text:
  return read("skills://", on=on)


def skill(name: str = "", show: Show = HEAD, on: str = "") -> Act[Text]:
  def ear(id: str):
    yield opened(id, "Text", name=name)
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if isinstance(got, Text):
            yield told(id, "done", text=shown(got, show))
          return

  return skill_made(Text, act("skill", on, controlled(ear, lasting=True), name))


def skill_made[T](_shape: type[T], made) -> Act[T]:
  return made


async def listed(on: str = "") -> None:
  skills(on)

compaction = """Compaction cuts this chain to the work that it still needs, and the chain goes on under its name.
- supersede(keep) cuts this chain to what the filter keep kept, and every act. compact() supersedes this chain with a
  filter that applies FILTERS in order, and its next word binds the summary
  that it is given and reads again each file whose read or write it kept, showing what changed. Its prompts, its
  rungs, the words that run and its module go on.
- A filter drops acts. latest() keeps the last read or write of each path, quiet() drops the commands, recent(n)
  keeps the acts of the last n replies, and await chosen() asks a model which acts to keep. together(*filters)
  applies filters in order.
- choice() asks a model which acts the work still needs, and what the rest holds, as ids and a summary.
- await condense() compacts this chain at once to what choice() chose, with the summary of the model, as compacted()
  does once. The command /compact of the TUI runs it on the chain on screen.
- clear() cuts this chain to nothing, with no summary: its model reads from zero, and the chain keeps its name, its
  module, its prompts and its threads. The command /clear of the TUI runs it on the chain on screen.
- compacted() wraps a chain: after an answer that reads more than SHARE of the window, it asks choice(), and at the
  next reply once that came, it compacts the chain to what the model chose. It moves, stops and pauses nothing. No
  chain is wrapped unless a word wraps it.
- A project changes the defaults in an extension of its own, whose word rebinds SHARE, FILTERS, CHOOSER, LISTED or
  BRIEF."""
SHARE = 0.6
CHOOSER = ""


LISTED = 40
BRIEF = """The chain below grows past its window, and it goes on with what the work still needs.
Choose what it keeps: each act that holds a decision or a ruling of the operator, a brief, a finding that the work
still needs, and the last state of each command that matters. A step keeps all that it made, and an act keeps the
step that made it. The chain keeps its module, its prompts and its steps, so keep no act for a value that the module
holds. It reads again each file whose read or write you keep and shows what changed since, so keep the last read or
write of each file that the work still needs, and no other.
Close with a tuple: the ids to keep, as list[str], and a summary, in a few short lines, of what the acts that you
drop hold and the work still needs to know."""


def together(*filters: Filter) -> Filter:
  def keep(acts: list) -> list:
    for one in filters:
      acts = one(acts)
    return acts

  return keep


def latest() -> Filter:
  def keep(acts: list) -> list:
    last = {t.path: a[1] for a in acts if a[0] in ("read", "write") and isinstance(t := peek(a[1]), Text)}
    return [
      a for a in acts if a[0] not in ("read", "write") or a[1] in last.values() or not isinstance(peek(a[1]), Text)
    ]

  return keep


def quiet() -> Filter:
  return lambda acts: [a for a in acts if a[0] != "bash"]


def recent(n: int) -> Filter:
  def keep(acts: list) -> list:
    rungs = [a[2] for a in acts if a[0] == "reply"][-n:] if n > 0 else []
    return [a for a in acts if any(under(a[1], one) for one in rungs)]

  return keep


def choice(to: str = "", on: str = "") -> Act:
  here = on or scope(acting())
  words = program(here)
  acts = [a for a in transcript(here) if question(a) and a[0] not in ("reply", "run", "wants", "gate", "stand")]
  made: dict[str, list[str]] = {}
  for entry in acts:
    made.setdefault(entry[2], []).append(entry[1])
  lines = ["Open prompts:"]
  lines += [f"{a[1]} to {a[6] or 'its model'}: {a[5]!r:.300}" for a in acts if a[0] == "prompt" and not over(a[1])]
  lines.append("Acts:")
  for entry in acts:
    held = peek(entry[1])
    kilo = (
      len(held.content)
      if isinstance(held, Text)
      else len(held.stdout.content + held.stderr.content)
      if isinstance(held, Exit)
      else 0
    ) // 1000
    state = ("" if over(entry[1]) else " (open)") + (f" ({kilo}k chars)" if kilo else "")
    if (get(entry[2]) or ("",))[0] == "rung":
      if entry[1] in made[entry[2]][-LISTED:]:
        lines.append(f"  {entry[1]} {', '.join(map(repr, entry[4:]))[:120]}{state}")
    elif entry[0] == "rung":
      left = len(made.get(entry[1], [])) - LISTED
      word = " ".join(words.get(entry[1], "").split())[:160] or "(no word)"
      lines.append(
        f"{entry[1]} step of {entry[2]}{state}: {word}" + (f" ({left} earlier acts of it unlisted)" if left > 0 else "")
      )
    else:
      lines.append(f"{entry[1]} {', '.join(map(repr, entry[4:]))[:200]}{state}")
  brief = BRIEF + "\n\n" + "\n".join(lines)
  return prompt(tuple[list[str], str], brief, to=to or CHOOSER or automatic(), on=chain("chosen", on=here))


async def chosen(to: str = "", on: str = "") -> Filter:
  got = await choice(to, on)
  assert isinstance(got, tuple)
  return take(*got[0])


FILTERS: list[Filter] = [latest(), recent(8)]


def reground(on: str = "") -> None:
  here = on or scope(acting())
  voiced = {x[1] for x in transcript(here) if x[0] == "tell"}
  held: dict[str, Text] = {}
  for a in transcript(here):
    if (
      a[0] in ("read", "write")
      and a[1] in voiced
      and isinstance(t := peek(a[1]), Text)
      and "://" not in t.path
      and get(t.path.split("/")[0]) is None
    ):
      held[t.path] = t
  for path, text in held.items():
    try:
      read(path, differs(text.lines), on=on)
    except Refused:
      continue


def supersede(keep: Filter | None = None, on: str = "") -> str:
  here = on or scope(acting())
  theirs = transcript(here)
  kin = {here}
  acts = []
  for x in theirs:
    match x:
      case (str(kind), str(name), str(by), str(where), *words) if question(x):
        acts.append((kind, name, by, where, *words))
  for one in (keep or list)(acts):
    name = one[1]
    while name not in kin and (b := get(name)):
      kin.add(name)
      name = b[2]

  def stays(it: tuple) -> bool:
    made = get(it[1])
    if made is None:
      return it[2] in kin
    return question(it) or (made[2] if question(("reply", it[1])) else it[1]) in kin

  say("prefix", here, [it for it in theirs if stays(it)])
  return here


def compact(filters: list[Filter] | None = None, summary: str = "", on: str = "") -> str:
  here = supersede(together(*(FILTERS if filters is None else filters)), on)
  name = "summary"
  while f"</s:{name}>" in summary:
    name += "_"
  quoted = f"<s:{name}>\n{summary}</s:{name}>\n" if summary else ""
  rung(f"{quoted}reground()", on=here)
  return here


def clear(on: str = "") -> str:
  return supersede(lambda _: [], on)


def compacted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, pending, seen = scope(id), "", set()
    chose: tuple | None = None

    def keeping(ids: list[str], after: set) -> Filter:
      return lambda acts: take(*ids, *[a[1] for a in acts if a[1] not in after])(acts)

    while True:
      match (yield {id, here} | ({pending} if pending else set())):
        case ("done", about, _, value) if about == pending:
          chose = (None, "")
          match value:
            case (list() as listed, str() as summary):
              chose = ([keeping([i for i in listed if isinstance(i, str) and scope(i)], set(seen)), latest()], summary)
        case ("done", about, *_) if question(("reply", about)) and scope(about) == here and not (pending or chose):
          if (filled(about) or 0) > SHARE:
            seen = {fact[1] for fact in transcript(here) if question(fact)}
            pending = str(choice(on=here))
        case ("reply", about, *_) if chose and question(("reply", about)) and scope(about) == here:
          compact(chose[0], summary=chose[1].strip(), on=here)
          pending, chose = "", None

  return act("compacted", on, controlled(ear))


async def condense(to: str = "", on: str = "") -> str:
  here = on or scope(acting())
  before = {fact[1] for fact in transcript(here) if question(fact)}
  match await choice(to, here):
    case (list() as listed, str() as summary):
      ids = [i for i in listed if isinstance(i, str) and scope(i)]

      def chose(acts: list) -> list:
        return take(*ids, *[a[1] for a in acts if a[1] not in before])(acts)

      return compact([chose, latest()], summary.strip(), here)
  return compact(on=here)

naming = """name_session() names the session once, at the first message of the operator. It asks a name of the actor that
automatic() gives, on a chain of its own labelled naming, and with no such actor, or
with no name from it, the name is the first line of that message. The act of name_session() is done with the name.
rename_session(name) says the name that the operator chose, and its name wins over the name of name_session().
A client shows the name of the session that its record holds. The extension plays on the root alone."""
NAME_LONGEST = 60
NAME_BRIEF = """Give a name to a session of work, from the first message of its operator below: at most six words, in the
language of the message, that say what the work is, with no quotes and no period. Close with the name alone, as
close("Fix the login form").

The first message:
"""


def name_of(text: str) -> str:
  lines = [x.strip(" \t\"'`*#.") for x in text.splitlines()]
  return next((x[:NAME_LONGEST].rstrip() for x in lines if x), "")


def name_session(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here = scope(id)
    first = yield {id, "prompt"}
    while not (first[0] == "prompt" and operated(first[2])):
      first = yield {id, "prompt"}
    message = str(first[5])
    actor_of = automatic()
    given = None
    if actor_of:
      asked = prompt(str, NAME_BRIEF + message, to=actor_of, on=chain("naming", on=here))
      while not over(asked):
        yield {asked}
      given = peek(asked)
    yield "done", id, (isinstance(given, str) and name_of(given)) or name_of(message)

  return act("name_session", on, controlled(ear))


def rename_session(name: str, on: str = "") -> Act:
  def ear(id):
    yield "done", id, name.strip()

  return act("rename_session", on, ear)

import json


def enabled() -> list[str]:
  return list(dict.fromkeys(str(x[3]) for x in transcript(ROOT) if x[0] == "enable"))


def bound_by(on: str = "") -> dict[str, str]:
  found = {}
  for by, text in program(on).items():
    for line in text.splitlines():
      left, eq, right = line.partition("=")
      name = left.split(":")[0].strip() if eq and not right.startswith("=") else ""
      if line.startswith("<s:"):
        name = line[3:].split(">")[0]
      elif line.removeprefix("async ").startswith(("def ", "class ")):
        name = line.removeprefix("async ").split(None, 2)[1].split("(")[0].split(":")[0]
      if line[:1].strip() and name.isidentifier():
        found[name] = by
  return found


def extend(name: str, *rungs: str, tui: str = "") -> Text:
  words, folder = program(), f".furb/extensions/{name}"
  try:
    held = read(f"{folder}/{name}.py", HIDDEN).content
  except Refused:
    held = ""
  if tui:
    write(Text(f"{folder}/tui.ts", tui.strip("\n") + "\n"))
  else:
    try:
      tui = read(f"{folder}/tui.ts", HIDDEN).content
    except Refused:
      tui = ""
  try:
    skill = read(f"{folder}/SKILL.md", HIDDEN).content
  except Refused:
    skill = f"---\nname: {name}\ndescription: The extension {name} of this project.\n---\nThe extension {name} of this project.\n"
  head, _, body = skill[4:].partition("\n---\n") if skill.startswith("---\n") else ("", "", skill)
  kept = [x for x in head.splitlines() if not x.strip().startswith(("furb-word:", "furb-view:"))]
  kept = kept if "metadata:" in kept else [*kept, "metadata:"]
  at = kept.index("metadata:") + 1
  kept[at:at] = [f"  furb-word: {name}.py", *(["  furb-view: tui.ts"] if tui else [])]
  write(Text(f"{folder}/SKILL.md", "---\n" + "\n".join(kept) + "\n---\n" + body))
  landed = write(
    Text(f"{folder}/{name}.py", "\n\n".join([held.strip("\n"), *(words[one] for one in rungs)]).strip("\n") + "\n")
  )
  try:
    config = json.loads(read(".furb/config.json", HIDDEN).content)
  except Refused:
    config = {}
  config.setdefault("extensions", {})[name] = f"extensions/{name}"
  write(Text(".furb/config.json", json.dumps(config, indent=2) + "\n"))
  return landed

web = """web_search(query) searches the web with the search of the provider of your actor, or with a free search when
it has none, and web_fetch(url) reads a page, as Markdown when it is HTML. Each gives an act of Text to await, which
tells its text with its show when it is done, as a read does."""


def text_act(kind: str, on: str, show: Show, word: str, *words: str) -> Act:
  def ear(id: str):
    yield opened(id, "Text", **{word: words[0]})
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if isinstance(got, Text):
            yield told(id, "done", text=shown(got, show))
          return

  return act(kind, on, controlled(ear, lasting=True), *words)


def web_search(query: str, to: str = "", show: Show = HEAD, on: str = "") -> Act:
  return text_act("search", on, show, "query", query, to or str(module(on).get("actor", "")))


def web_fetch(url: str, show: Show = HEAD, on: str = "") -> Act:
  return text_act("fetch", on, show, "url", url)

import json


mcp = """MCP servers give you tools, resources and prompts. The index that this chain was told lists each server with its
state and its tools, and names the class that holds the tools of a server: await its methods, as
await github.create_issue(...), each of which gives an McpResult, a dict with text, content and structured.
- mcp_tools(server) tells the signature of each tool of a server, and mcp_tool(server, name) tells the whole schema of
  one.
- mcp_use(server) binds the class of a server that the index left unbound. Use the class in your next reply, since this
  reply cannot name it.
- mcp_call(server, tool, arguments) calls a tool with the original names of its arguments. A tool that fails raises
  Refused with its text.
- mcp_read(server, uri) reads a resource, and mcp_prompt(server, name, arguments) expands a prompt. @server:uri in a
  message of the operator names a resource: read it with mcp_read.
- mcp_servers() lists the servers as dicts, and mcp_control(action, server) does reconnect, enable, disable, approve,
  login or logout."""
BIND = 3000

type McpResult = dict


def mcp_type(schema: object) -> str:
  if not isinstance(schema, dict):
    return "Any"
  kind = schema.get("type")
  options = schema.get("anyOf") or schema.get("oneOf")
  if isinstance(options, list) and options:
    found = " | ".join({mcp_type(x): 0 for x in options})
  elif "const" in schema:
    found = f"Literal[{schema['const']!r}]"
  elif isinstance(schema.get("enum"), list) and schema["enum"]:
    found = "Literal[" + ", ".join(repr(x) for x in schema["enum"]) + "]"
  elif isinstance(kind, list):
    found = " | ".join({mcp_type({**schema, "type": x}): 0 for x in kind}) or "Any"
  elif kind == "array":
    found = f"list[{mcp_type(schema.get('items'))}]"
  else:
    names = {
      "string": "str",
      "integer": "int",
      "number": "float",
      "boolean": "bool",
      "null": "None",
      "object": "dict[str, Any]",
    }
    found = names.get(kind, "Any") if isinstance(kind, str) else "Any"
  return found


def mcp_signature(tool: dict) -> str:
  schema = tool.get("input") or {}
  props = schema.get("properties") or {}
  need = schema.get("required") or []
  args = [f"{n}: {mcp_type(p)}" for n, p in props.items() if n in need]
  args += [f"{n}: {mcp_type(p)} | None = None" for n, p in props.items() if n not in need]
  text = " ".join(str(tool.get("description") or "").split())
  cut = text.find(". ")
  first = (text if cut < 0 else text[: cut + 1])[:200]
  line = f"{tool['name']}({', '.join(args)})"
  return f"{line}: {first}" if first else line


def mcp_line(server: dict) -> str:
  name, state = server["name"], server["state"]
  line = f"{name} {state}"
  if state == "failed":
    return f"{line}: {server.get('error') or 'no reason given'}"
  if state == "needs-auth":
    return f"{line}: mcp_control('login', {name!r}) signs in"
  if state == "unapproved":
    return f"{line}: mcp_control('approve', {name!r}) lets it run"
  if state != "connected":
    return line
  tools = [str(x["name"]) for x in server.get("tools") or []]
  more = f", and {len(tools[12:])} more" if tools[12:] else ""
  parts = [f"{len(tools)} tools ({', '.join(tools[:12])}{more})" if tools else "no tools"]
  sorts = (
    (len(server.get("resources") or []) + len(server.get("templates") or []), "resources"),
    (len(server.get("prompts") or []), "prompts"),
  )
  parts += [f"{count} {noun}" for count, noun in sorts if count]
  said = " ".join(str(server.get("instructions") or "").split())
  return f"{line}, {', '.join(parts)}" + (f". Instructions: {said[:400]}" if said else "")


def mcp_closed(got: object, show: Show) -> dict:
  if isinstance(got, list):
    return {"servers": "\n".join(mcp_line(x) for x in got)}
  if isinstance(got, dict) and "name" in got:
    return {"server": mcp_line(got)}
  if isinstance(got, dict):
    images = [f"![image]({x['image']})" for x in got.get("content") or [] if x.get("type") == "image"]
    lines = [shown(Text("", str(got.get("text") or "")), show), *images]
    return {"text": "\n".join(x for x in lines if x)}
  return {}


def mcp_act(kind: str, on: str, of: str, fields: dict, show: Show, *words: object) -> Act:
  def ear(id: str):
    yield opened(id, of, **fields)
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if not isinstance(got, BaseException):
            yield told(id, "done", **mcp_closed(got, show))
          return

  return act(kind, on, controlled(ear, lasting=True), *words)


def mcp_made[T](_shape: type[T], made) -> Act[T]:
  return made


def mcp_known(server: str, on: str = "") -> dict:
  held = answer("mcp_servers", on, [])
  for one in held:
    if one["name"] == server:
      return one
  why = f"No server {server} is known. The servers are: {', '.join(str(x['name']) for x in held) or 'none'}."
  raise Refused(why)


def mcp_named(word: str) -> str:
  at = ("\n" + word).find("\nclass ")
  if at < 0:
    return ""
  end = at + 6
  while end < len(word) and (word[end].isalnum() or word[end] == "_"):
    end += 1
  return word[at + 6 : end]


def mcp_bound(server: dict, on: str = "") -> str:
  word = str(server.get("binding") or "")
  name = mcp_named(word)
  if not name:
    return word
  calls = [f"mcp_call({json.dumps(server['name'])}", "mcp_call('" + str(server["name"]) + "'"]
  held = module(on)
  words = list(program(on).values())

  def own(cls: str) -> bool:
    return any((f"class {cls}:" in w or f"class {cls}(" in w) and any(c in w for c in calls) for w in words)

  free, n = name, 1
  while free in held and not own(free):
    n += 1
    free = f"{name}_{n}"
  at = ("\n" + word).find("\nclass ") + 6
  return word if free == name else word[:at] + free + word[at + len(name) :]


def mcp_servers(on: str = "") -> Act[list[dict]]:
  return mcp_made(list, mcp_act("mcp_servers", on, "list[dict]", {}, HEAD))


def mcp_call(server: str, tool: str, arguments: dict | None = None, show: Show = HEAD, on: str = "") -> Act[McpResult]:
  given = dict(arguments or {})
  fields = {"server": server, "tool": tool, **({"arguments": given} if given and not repr(given)[200:] else {})}
  return mcp_made(dict, mcp_act("mcp_call", on, "McpResult", fields, show, server, tool, given))


def mcp_read(server: str, uri: str, show: Show = HEAD, on: str = "") -> Act[McpResult]:
  return mcp_made(dict, mcp_act("mcp_read", on, "McpResult", {"server": server, "uri": uri}, show, server, uri))


def mcp_prompt(
  server: str, name: str, arguments: dict | None = None, show: Show = HEAD, on: str = ""
) -> Act[McpResult]:
  given = {str(k): str(v) for k, v in (arguments or {}).items()}
  fields = {"server": server, "name": name, **({"arguments": given} if given else {})}
  return mcp_made(dict, mcp_act("mcp_prompt", on, "McpResult", fields, show, server, name, given))


def mcp_control(action: str, server: str, on: str = "") -> Act[dict]:
  if action not in ("reconnect", "enable", "disable", "approve", "login", "logout"):
    why = f"No action {action}: use reconnect, enable, disable, approve, login or logout."
    raise Refused(why)
  return mcp_made(dict, mcp_act("mcp_control", on, "dict", {"action": action, "server": server}, HEAD, action, server))


def mcp_tools(server: str, on: str = "") -> Act[str]:
  def ear(id: str):
    try:
      text = "\n".join(mcp_signature(x) for x in mcp_known(server, on).get("tools") or [])
    except Refused as why:
      yield told(id, "", server=server, error=str(why))
      yield "done", id, why
      return
    yield opened(id, "str", server=server, tools=text or "none")
    yield "done", id, text

  return mcp_made(str, act("mcp_tools", on, ear, server))


def mcp_tool(server: str, name: str, on: str = "") -> Act[dict]:
  def pretty(value: object) -> str | None:
    return json.dumps(value, indent=1) if value else None

  def ear(id: str):
    fault = None
    try:
      tools = mcp_known(server, on).get("tools") or []
    except Refused as why:
      tools, fault = [], why
    tool = next((x for x in tools if x["name"] == name), None)
    fault = fault or (None if tool else Refused(f"No tool {name} on {server}."))
    if fault or tool is None:
      yield told(id, "", server=server, tool=name, error=str(fault))
      yield "done", id, fault
      return
    yield opened(
      id,
      "dict",
      server=server,
      tool=name,
      title=tool.get("title"),
      description=tool.get("description"),
      input=pretty(tool.get("input")),
      output=pretty(tool.get("output")),
      annotations=pretty(tool.get("annotations")),
    )
    yield "done", id, tool

  return mcp_made(dict, act("mcp_tool", on, ear, server, name))


def mcp_use(server: str, on: str = "") -> Act:
  word = mcp_bound(mcp_known(server, on), on)
  if not word:
    why = f"{server} has no tools to bind."
    raise Refused(why)
  return rung(word, on=on)


def mcp_index(on: str = "") -> Act:
  def ear(id: str):
    yield "started", id
    seen: dict[str, tuple] = {}
    made: list[str] = []
    pending = act("mcp_servers", on, None)
    while True:
      if pending and over(pending):
        got, pending = peek(pending), ""
        if isinstance(got, list):
          now = {}
          for x in got:
            line, word = mcp_line(x), str(x.get("binding") or "")
            if x["state"] != "connected":
              word = ""
            elif word and len(word) <= BIND:
              word = mcp_bound(x, on)
              line += f". Class {mcp_named(word)}."
            elif word:
              line += f". mcp_use({x['name']!r}) binds its class."
              word = ""
