compaction = """Compaction cuts this chain to the work that it still needs, and the chain goes on under its name.
- supersede(keep) cuts this chain to what the filter keep kept, and every act. compact() supersedes this chain with a
  filter that applies FILTERS in order, and its next word binds the summary
  that it is given and reads again each file whose read or write it kept, showing what changed. Its prompts, its
  rungs, the words that run and its module go on.
- A filter drops acts. latest() keeps the last read or write of each path, quiet() drops the commands, recent(n)
  keeps the acts of the last n replies, and await chosen() asks a model which acts to keep. together(*filters)
  applies filters in order.
- choice() asks a model which acts the work still needs, and what the rest holds, as ids and a summary.
- await condense() compacts this chain at once to what choice() chose, with the summary of the model, as compacted()
  does once. The command /compact of the TUI runs it on the chain on screen.
- clear() cuts this chain to nothing, with no summary: its model reads from zero, and the chain keeps its name, its
  module, its prompts and its threads. The command /clear of the TUI runs it on the chain on screen.
- compacted() wraps a chain: after an answer that reads more than SHARE of the window, it asks choice(), and at the
  next reply once that came, it compacts the chain to what the model chose. It moves, stops and pauses nothing. No
  chain is wrapped unless a word wraps it.
- A project changes the defaults in an extension of its own, whose word rebinds SHARE, FILTERS, CHOOSER, LISTED or
  BRIEF."""
SHARE = 0.6
CHOOSER = ""


LISTED = 40
BRIEF = """The chain below grows past its window, and it goes on with what the work still needs.
Choose what it keeps: each act that holds a decision or a ruling of the operator, a brief, a finding that the work
still needs, and the last state of each command that matters. A step keeps all that it made, and an act keeps the
step that made it. The chain keeps its module, its prompts and its steps, so keep no act for a value that the module
holds. It reads again each file whose read or write you keep and shows what changed since, so keep the last read or
write of each file that the work still needs, and no other.
Close with a tuple: the ids to keep, as list[str], and a summary, in a few short lines, of what the acts that you
drop hold and the work still needs to know."""


def together(*filters: Filter) -> Filter:
  def keep(acts: list) -> list:
    for one in filters:
      acts = one(acts)
    return acts

  return keep


def latest() -> Filter:
  def keep(acts: list) -> list:
    last = {t.path: a[1] for a in acts if a[0] in ("read", "write") and isinstance(t := peek(a[1]), Text)}
    return [
      a for a in acts if a[0] not in ("read", "write") or a[1] in last.values() or not isinstance(peek(a[1]), Text)
    ]

  return keep


def quiet() -> Filter:
  return lambda acts: [a for a in acts if a[0] != "bash"]


def recent(n: int) -> Filter:
  def keep(acts: list) -> list:
    rungs = [a[2] for a in acts if a[0] == "reply"][-n:] if n > 0 else []
    return [a for a in acts if any(under(a[1], one) for one in rungs)]

  return keep


def choice(to: str = "", on: str = "") -> Act:
  here = on or scope(acting())
  words = program(here)
  acts = [a for a in transcript(here) if question(a) and a[0] not in ("reply", "run", "wants", "gate", "stand")]
  made: dict[str, list[str]] = {}
  for entry in acts:
    made.setdefault(entry[2], []).append(entry[1])
  lines = ["Open prompts:"]
  lines += [f"{a[1]} to {a[6] or 'its model'}: {a[5]!r:.300}" for a in acts if a[0] == "prompt" and not over(a[1])]
  lines.append("Acts:")
  for entry in acts:
    held = peek(entry[1])
    kilo = (
      len(held.content)
      if isinstance(held, Text)
      else len(held.stdout.content + held.stderr.content)
      if isinstance(held, Exit)
      else 0
    ) // 1000
    state = ("" if over(entry[1]) else " (open)") + (f" ({kilo}k chars)" if kilo else "")
    if (get(entry[2]) or ("",))[0] == "rung":
      if entry[1] in made[entry[2]][-LISTED:]:
        lines.append(f"  {entry[1]} {', '.join(map(repr, entry[4:]))[:120]}{state}")
    elif entry[0] == "rung":
      left = len(made.get(entry[1], [])) - LISTED
      word = " ".join(words.get(entry[1], "").split())[:160] or "(no word)"
      lines.append(
        f"{entry[1]} step of {entry[2]}{state}: {word}" + (f" ({left} earlier acts of it unlisted)" if left > 0 else "")
      )
    else:
      lines.append(f"{entry[1]} {', '.join(map(repr, entry[4:]))[:200]}{state}")
  brief = BRIEF + "\n\n" + "\n".join(lines)
  return prompt(tuple[list[str], str], brief, to=to or CHOOSER or automatic(), on=chain("chosen", on=here))


async def chosen(to: str = "", on: str = "") -> Filter:
  got = await choice(to, on)
  assert isinstance(got, tuple)
  return take(*got[0])


FILTERS: list[Filter] = [latest(), recent(8)]


def reground(on: str = "") -> None:
  here = on or scope(acting())
  voiced = {x[1] for x in transcript(here) if x[0] == "tell"}
  held: dict[str, Text] = {}
  for a in transcript(here):
    if (
      a[0] in ("read", "write")
      and a[1] in voiced
      and isinstance(t := peek(a[1]), Text)
      and "://" not in t.path
      and get(t.path.split("/")[0]) is None
    ):
      held[t.path] = t
  for path, text in held.items():
    try:
      read(path, differs(text.lines), on=on)
    except Refused:
      continue


def supersede(keep: Filter | None = None, on: str = "") -> str:
  here = on or scope(acting())
  theirs = transcript(here)
  kin = {here}
  acts = []
  for x in theirs:
    match x:
      case (str(kind), str(name), str(by), str(where), *words) if question(x):
        acts.append((kind, name, by, where, *words))
  for one in (keep or list)(acts):
    name = one[1]
    while name not in kin and (b := get(name)):
      kin.add(name)
      name = b[2]

  def stays(it: tuple) -> bool:
    made = get(it[1])
    if made is None:
      return it[2] in kin
    return question(it) or (made[2] if question(("reply", it[1])) else it[1]) in kin

  say("prefix", here, [it for it in theirs if stays(it)])
  return here


def compact(filters: list[Filter] | None = None, summary: str = "", on: str = "") -> str:
  here = supersede(together(*(FILTERS if filters is None else filters)), on)
  name = "summary"
  while f"</s:{name}>" in summary:
    name += "_"
  quoted = f"<s:{name}>\n{summary}</s:{name}>\n" if summary else ""
  rung(f"{quoted}reground()", on=here)
  return here


def clear(on: str = "") -> str:
  return supersede(lambda _: [], on)


def compacted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, pending, seen = scope(id), "", set()
    chose: tuple | None = None

    def keeping(ids: list[str], after: set) -> Filter:
      return lambda acts: take(*ids, *[a[1] for a in acts if a[1] not in after])(acts)

    while True:
      match (yield {id, here} | ({pending} if pending else set())):
        case ("done", about, _, value) if about == pending:
          chose = (None, "")
          match value:
            case (list() as listed, str() as summary):
              chose = ([keeping([i for i in listed if isinstance(i, str) and scope(i)], set(seen)), latest()], summary)
        case ("done", about, *_) if question(("reply", about)) and scope(about) == here and not (pending or chose):
          if (filled(about) or 0) > SHARE:
            seen = {fact[1] for fact in transcript(here) if question(fact)}
            pending = str(choice(on=here))
        case ("reply", about, *_) if chose and question(("reply", about)) and scope(about) == here:
          compact(chose[0], summary=chose[1].strip(), on=here)
          pending, chose = "", None

  return act("compacted", on, controlled(ear))


async def condense(to: str = "", on: str = "") -> str:
  here = on or scope(acting())
  before = {fact[1] for fact in transcript(here) if question(fact)}
  match await choice(to, here):
    case (list() as listed, str() as summary):
      ids = [i for i in listed if isinstance(i, str) and scope(i)]

      def chose(acts: list) -> list:
        return take(*ids, *[a[1] for a in acts if a[1] not in before])(acts)

      return compact([chose, latest()], summary.strip(), here)
  return compact(on=here)

import json


def enabled() -> list[str]:
  return list(dict.fromkeys(str(x[3]) for x in transcript(ROOT) if x[0] == "enable"))


def bound_by(on: str = "") -> dict[str, str]:
  found = {}
  for by, text in program(on).items():
    for line in text.splitlines():
      left, eq, right = line.partition("=")
      name = left.split(":")[0].strip() if eq and not right.startswith("=") else ""
      if line.startswith("<s:"):
        name = line[3:].split(">")[0]
      elif line.removeprefix("async ").startswith(("def ", "class ")):
        name = line.removeprefix("async ").split(None, 2)[1].split("(")[0].split(":")[0]
      if line[:1].strip() and name.isidentifier():
        found[name] = by
  return found


def extend(name: str, *rungs: str, tui: str = "") -> Text:
  words, folder = program(), f".furb/extensions/{name}"
  try:
    held = read(f"{folder}/{name}.py", HIDDEN).content
  except Refused:
    held = ""
  if tui:
    write(Text(f"{folder}/tui.ts", tui.strip("\n") + "\n"))
  else:
    try:
      tui = read(f"{folder}/tui.ts", HIDDEN).content
    except Refused:
      tui = ""
  try:
    skill = read(f"{folder}/SKILL.md", HIDDEN).content
  except Refused:
    skill = f"---\nname: {name}\ndescription: The extension {name} of this project.\n---\nThe extension {name} of this project.\n"
  head, _, body = skill[4:].partition("\n---\n") if skill.startswith("---\n") else ("", "", skill)
  kept = [x for x in head.splitlines() if not x.strip().startswith(("furb-word:", "furb-view:"))]
  kept = kept if "metadata:" in kept else [*kept, "metadata:"]
  at = kept.index("metadata:") + 1
  kept[at:at] = [f"  furb-word: {name}.py", *(["  furb-view: tui.ts"] if tui else [])]
  write(Text(f"{folder}/SKILL.md", "---\n" + "\n".join(kept) + "\n---\n" + body))
  landed = write(
    Text(f"{folder}/{name}.py", "\n\n".join([held.strip("\n"), *(words[one] for one in rungs)]).strip("\n") + "\n")
  )
  try:
    config = json.loads(read(".furb/config.json", HIDDEN).content)
  except Refused:
    config = {}
  config.setdefault("extensions", {})[name] = f"extensions/{name}"
  write(Text(".furb/config.json", json.dumps(config, indent=2) + "\n"))
  return landed

web = """web_search(query) searches the web with the search of the provider of your actor, or with a free search when
it has none, and web_fetch(url) reads a page, as Markdown when it is HTML. Each gives an act of Text to await, which
tells its text with its show when it is done, as a read does."""


def text_act(kind: str, on: str, show: Show, word: str, *words: str) -> Act:
  def ear(id: str):
    yield opened(id, "Text", **{word: words[0]})
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if isinstance(got, Text):
            yield told(id, "done", text=shown(got, show))
          return

  return act(kind, on, controlled(ear, lasting=True), *words)


def web_search(query: str, to: str = "", show: Show = HEAD, on: str = "") -> Act:
  return text_act("search", on, show, "query", query, to or str(module(on).get("actor", "")))


def web_fetch(url: str, show: Show = HEAD, on: str = "") -> Act:
  return text_act("fetch", on, show, "url", url)

import json


mcp = """MCP servers give you tools, resources and prompts. The index that this chain was told lists each server with its
state and its tools, and names the class that holds the tools of a server: await its methods, as
await github.create_issue(...), each of which gives an McpResult, a dict with text, content and structured.
- mcp_tools(server) tells the signature of each tool of a server, and mcp_tool(server, name) tells the whole schema of
  one.
- mcp_use(server) binds the class of a server that the index left unbound. Use the class in your next reply, since this
  reply cannot name it.
- mcp_call(server, tool, arguments) calls a tool with the original names of its arguments. A tool that fails raises
  Refused with its text.
- mcp_read(server, uri) reads a resource, and mcp_prompt(server, name, arguments) expands a prompt. @server:uri in a
  message of the operator names a resource: read it with mcp_read.
- mcp_servers() lists the servers as dicts, and mcp_control(action, server) does reconnect, enable, disable, approve,
  login or logout."""
BIND = 3000

type McpResult = dict


def mcp_type(schema: object) -> str:
  if not isinstance(schema, dict):
    return "Any"
  kind = schema.get("type")
  options = schema.get("anyOf") or schema.get("oneOf")
  if isinstance(options, list) and options:
    found = " | ".join({mcp_type(x): 0 for x in options})
  elif "const" in schema:
    found = f"Literal[{schema['const']!r}]"
  elif isinstance(schema.get("enum"), list) and schema["enum"]:
    found = "Literal[" + ", ".join(repr(x) for x in schema["enum"]) + "]"
  elif isinstance(kind, list):
    found = " | ".join({mcp_type({**schema, "type": x}): 0 for x in kind}) or "Any"
  elif kind == "array":
    found = f"list[{mcp_type(schema.get('items'))}]"
  else:
    names = {
      "string": "str",
      "integer": "int",
      "number": "float",
      "boolean": "bool",
      "null": "None",
      "object": "dict[str, Any]",
    }
    found = names.get(kind, "Any") if isinstance(kind, str) else "Any"
  return found


def mcp_signature(tool: dict) -> str:
  schema = tool.get("input") or {}
  props = schema.get("properties") or {}
  need = schema.get("required") or []
  args = [f"{n}: {mcp_type(p)}" for n, p in props.items() if n in need]
  args += [f"{n}: {mcp_type(p)} | None = None" for n, p in props.items() if n not in need]
  text = " ".join(str(tool.get("description") or "").split())
  cut = text.find(". ")
  first = (text if cut < 0 else text[: cut + 1])[:200]
  line = f"{tool['name']}({', '.join(args)})"
  return f"{line}: {first}" if first else line


def mcp_line(server: dict) -> str:
  name, state = server["name"], server["state"]
  line = f"{name} {state}"
  if state == "failed":
    return f"{line}: {server.get('error') or 'no reason given'}"
  if state == "needs-auth":
    return f"{line}: mcp_control('login', {name!r}) signs in"
  if state == "unapproved":
    return f"{line}: mcp_control('approve', {name!r}) lets it run"
  if state != "connected":
    return line
  tools = [str(x["name"]) for x in server.get("tools") or []]
  more = f", and {len(tools[12:])} more" if tools[12:] else ""
  parts = [f"{len(tools)} tools ({', '.join(tools[:12])}{more})" if tools else "no tools"]
  sorts = (
    (len(server.get("resources") or []) + len(server.get("templates") or []), "resources"),
    (len(server.get("prompts") or []), "prompts"),
  )
  parts += [f"{count} {noun}" for count, noun in sorts if count]
  said = " ".join(str(server.get("instructions") or "").split())
  return f"{line}, {', '.join(parts)}" + (f". Instructions: {said[:400]}" if said else "")


def mcp_closed(got: object, show: Show) -> dict:
  if isinstance(got, list):
    return {"servers": "\n".join(mcp_line(x) for x in got)}
  if isinstance(got, dict) and "name" in got:
    return {"server": mcp_line(got)}
  if isinstance(got, dict):
    images = [f"![image]({x['image']})" for x in got.get("content") or [] if x.get("type") == "image"]
    lines = [shown(Text("", str(got.get("text") or "")), show), *images]
    return {"text": "\n".join(x for x in lines if x)}
  return {}


def mcp_act(kind: str, on: str, of: str, fields: dict, show: Show, *words: object) -> Act:
  def ear(id: str):
    yield opened(id, of, **fields)
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if not isinstance(got, BaseException):
            yield told(id, "done", **mcp_closed(got, show))
          return

  return act(kind, on, controlled(ear, lasting=True), *words)


def mcp_made[T](_shape: type[T], made) -> Act[T]:
  return made


def mcp_known(server: str, on: str = "") -> dict:
  held = answer("mcp_servers", on, [])
  for one in held:
    if one["name"] == server:
      return one
  why = f"No server {server} is known. The servers are: {', '.join(str(x['name']) for x in held) or 'none'}."
  raise Refused(why)


def mcp_named(word: str) -> str:
  at = ("\n" + word).find("\nclass ")
  if at < 0:
    return ""
  end = at + 6
  while end < len(word) and (word[end].isalnum() or word[end] == "_"):
    end += 1
  return word[at + 6 : end]


def mcp_bound(server: dict, on: str = "") -> str:
  word = str(server.get("binding") or "")
  name = mcp_named(word)
  if not name:
    return word
  calls = [f"mcp_call({json.dumps(server['name'])}", "mcp_call('" + str(server["name"]) + "'"]
  held = module(on)
  words = list(program(on).values())

  def own(cls: str) -> bool:
    return any((f"class {cls}:" in w or f"class {cls}(" in w) and any(c in w for c in calls) for w in words)

  free, n = name, 1
  while free in held and not own(free):
    n += 1
    free = f"{name}_{n}"
  at = ("\n" + word).find("\nclass ") + 6
  return word if free == name else word[:at] + free + word[at + len(name) :]


def mcp_servers(on: str = "") -> Act[list[dict]]:
  return mcp_made(list, mcp_act("mcp_servers", on, "list[dict]", {}, HEAD))


def mcp_call(server: str, tool: str, arguments: dict | None = None, show: Show = HEAD, on: str = "") -> Act[McpResult]:
  given = dict(arguments or {})
  fields = {"server": server, "tool": tool, **({"arguments": given} if given and not repr(given)[200:] else {})}
  return mcp_made(dict, mcp_act("mcp_call", on, "McpResult", fields, show, server, tool, given))


def mcp_read(server: str, uri: str, show: Show = HEAD, on: str = "") -> Act[McpResult]:
  return mcp_made(dict, mcp_act("mcp_read", on, "McpResult", {"server": server, "uri": uri}, show, server, uri))


def mcp_prompt(
  server: str, name: str, arguments: dict | None = None, show: Show = HEAD, on: str = ""
) -> Act[McpResult]:
  given = {str(k): str(v) for k, v in (arguments or {}).items()}
  fields = {"server": server, "name": name, **({"arguments": given} if given else {})}
  return mcp_made(dict, mcp_act("mcp_prompt", on, "McpResult", fields, show, server, name, given))


def mcp_control(action: str, server: str, on: str = "") -> Act[dict]:
  if action not in ("reconnect", "enable", "disable", "approve", "login", "logout"):
    why = f"No action {action}: use reconnect, enable, disable, approve, login or logout."
    raise Refused(why)
  return mcp_made(dict, mcp_act("mcp_control", on, "dict", {"action": action, "server": server}, HEAD, action, server))


def mcp_tools(server: str, on: str = "") -> Act[str]:
  def ear(id: str):
    try:
      text = "\n".join(mcp_signature(x) for x in mcp_known(server, on).get("tools") or [])
    except Refused as why:
      yield told(id, "", server=server, error=str(why))
      yield "done", id, why
      return
    yield opened(id, "str", server=server, tools=text or "none")
    yield "done", id, text

  return mcp_made(str, act("mcp_tools", on, ear, server))


def mcp_tool(server: str, name: str, on: str = "") -> Act[dict]:
  def pretty(value: object) -> str | None:
    return json.dumps(value, indent=1) if value else None

  def ear(id: str):
    fault = None
    try:
      tools = mcp_known(server, on).get("tools") or []
    except Refused as why:
      tools, fault = [], why
    tool = next((x for x in tools if x["name"] == name), None)
    fault = fault or (None if tool else Refused(f"No tool {name} on {server}."))
    if fault or tool is None:
      yield told(id, "", server=server, tool=name, error=str(fault))
      yield "done", id, fault
      return
    yield opened(
      id,
      "dict",
      server=server,
      tool=name,
      title=tool.get("title"),
      description=tool.get("description"),
      input=pretty(tool.get("input")),
      output=pretty(tool.get("output")),
      annotations=pretty(tool.get("annotations")),
    )
    yield "done", id, tool

  return mcp_made(dict, act("mcp_tool", on, ear, server, name))


def mcp_use(server: str, on: str = "") -> Act:
  word = mcp_bound(mcp_known(server, on), on)
  if not word:
    why = f"{server} has no tools to bind."
    raise Refused(why)
  return rung(word, on=on)


def mcp_index(on: str = "") -> Act:
  def ear(id: str):
    yield "started", id
    seen: dict[str, tuple] = {}
    made: list[str] = []
    pending = act("mcp_servers", on, None)
    while True:
      if pending and over(pending):
        got, pending = peek(pending), ""
        if isinstance(got, list):
          now = {}
          for x in got:
            line, word = mcp_line(x), str(x.get("binding") or "")
            if x["state"] != "connected":
              word = ""
            elif word and len(word) <= BIND:
              word = mcp_bound(x, on)
              line += f". Class {mcp_named(word)}."
            elif word:
              line += f". mcp_use({x['name']!r}) binds its class."
              word = ""
            now[x["name"]] = (line, word)
          lines = [v[0] for k, v in now.items() if seen.get(k, ("", ""))[0] != v[0]]
          lines += [f"{k} is gone" for k in seen if k not in now]
          if lines:
            yield told(id, "changed" if seen else "", servers="\n".join(lines))
          for name, (_, word) in now.items():
            if word and seen.get(name, ("", ""))[1] != word:
              made.append(rung(word, on=on))
          seen = now
      if not (pending or over(id)) and all(map(over, made)):
        yield "done", id, None
      a = yield {id, "mcp_changed", *made} | ({pending} if pending else set())
      if isinstance(peek(id), BaseException) or (a[0] in ("cancel", "close") and covers(a, id)):
        return
      pending = act("mcp_servers", on, None) if a[0] == "mcp_changed" else pending

  return act("mcp_index", on, controlled(ear, lasting=True))

chains.definitions:
CAP = 40

BUDGET = 4096

def catchup(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here = scope(id)
    if here == ROOT:
      act("clock", here, None)
    while True:
      match (yield {id, "stand"}):
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          if here == ROOT:
            act("clock", here, None)
          seen: dict[str, object] = {}
          for fact in transcript(here)[::-1]:
            if fact[0] not in ("read", "write") or (fact[0] == "read" and str(fact[4]).endswith(("/", "\\"))):
              continue
            was = peek(fact[1])
            path = was.path if isinstance(was, Text) else str(fact[4])
            if path in seen:
              continue
            seen[path] = None
            if isinstance(was, Text) and "://" not in path and get(path.split("/")[0]) is None:
              try:
                now = read(path, HIDDEN, here).lines
              except Refused:
                seen[path] = "gone"
                continue
              lines = {i: now[i - 1] for i in differs(was.lines)(now)}
              lines |= dict.fromkeys(range(len(now) + 1, len(was.lines) + 1))
              seen[path] = len(lines) if len(lines) > CAP else lines or None
          clocks = [x for one in transcript(ROOT, "clock") if isinstance(x := peek(one[1]), float)][-2:] or [0.0]
          hours = (clocks[-1] - clocks[0]) / 3600
          changed: dict | list = {key: value for key, value in seen.items() if value}
          kept = len(changed)
          while True:
            paragraph = headed(here, "caught up", hours=round(hours, 1) if hours > 1 else None, changed=changed or None)
            if len(paragraph.encode()) <= BUDGET:
              break
            changed = [*changed][:kept]
            kept -= 1
          if "\n" in paragraph:
            yield "tell", here, [paragraph]

  return act("catchup", on, ear)

NAMES = ("AGENTS.md", "CLAUDE.md")

LOCAL = ("AGENTS.local.md", "CLAUDE.local.md")

def lacking(known: set[str]) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if line not in known]

def remembered(path: str) -> bool:
  return path.replace("\\", "/").rsplit("/", 1)[-1] in (*NAMES, *LOCAL)

def joined(folder: str, name: str) -> str:
  return folder + name if folder.endswith(("/", "\\")) else folder + "/" + name

def looked(path: str, on: str = "") -> Text | None:
  try:
    return read(path, HIDDEN, on)
  except Refused:
    return None

def pieces(path: str) -> list[str]:
  kept: list[str] = []
  for one in path.replace("\\", "/").split("/"):
    if one == ".." and kept and kept[-1] not in ("", ".."):
      kept.pop()
    elif one not in (".", "") or not kept:
      kept.append(one)
  return kept

def folders(path: str = ".", on: str = "") -> list[Text]:
  up: list[Text] = []
  at = "./"
  while (got := looked(at, on)) is not None and not (up and got.path == up[-1].path):
    up.append(got)
    at = joined(got.path, "../")
  down: list[Text] = []
  if up and "://" not in path:
    here = pieces(up[0].path)
    absolute = path.startswith(("/", "\\", "~")) or path[1:3] in (":/", ":\\")
    full = pieces(path if absolute else joined(up[0].path, path))
    held = up[0]
    for one in full[len(here) :] if full[: len(here)] == here else []:
      if one + "/" not in held.lines or (deeper := looked(joined(held.path, one + "/"), on)) is None:
        break
      down.append(held := deeper)
  user = looked("config://", on)
  return [*([user] if user else []), *up[::-1], *down]

def memory(path: str = ".", on: str = "") -> list[Text]:
  was: dict[str, list[str]] = {}
  held: set[str] = set()
  for x in transcript(on):
    match x:
      case ("done", about, _, Text(place, content)) if (
        (question(("read", about)) or question(("write", about))) and get(maker := get(about)[2]) and tells(maker)
      ):
        was[place] = content.splitlines()
        if remembered(place):
          held.add(content)
  got: list[Text] = []
  for folder in folders(path, on):
    names = set(folder.lines)
    for group in NAMES, LOCAL:
      name = next((one for one in group if one in names), "")
      if not name or (found := looked(joined(folder.path, name), on)) is None:
        continue
      if found.content in held or any(one.path == found.path or one.content == found.content for one in got):
        continue
      got.append(found)
      mine = set(found.lines)
      near = max(was.values(), key=lambda kept: len(set(kept) & mine), default=[]) if found.path not in was else []
      if found.path in was:
        show = differs(was[found.path])
      elif mine and 2 * len(set(near) & mine) > len(mine):
        show = lacking(set(near))
      else:
        show = span(1, -1)
      tell(on, found.path, found, show)
  return got

async def recall(on: str = "") -> Act:
